/* Admin member workspace: uses the signed-in administrator and existing scoped reads. */
window.MioAdminMember={create(api){
 const {root,db,authorized,identity,esc,planName,countryOptions,countryBadge,safeImage,confirmSensitive,onClose,onSaved}=api;
 let member=null,record=null,owner=null,sequence=0,tab='dashboard',data={},errors={},busy=false,networkKind='generation',networkRootCode=null,networkSequence=0;
 let presentation=null,walletHistory=null,selectedWallet='cash';
 const tabs=[['dashboard','Dashboard'],['profile','Profile'],['wallets','Wallets'],['network','Tree / Network'],['earnings','Earnings'],['packages','Packages'],['orders','Orders'],['transactions','Transactions']];
 const n=v=>Number(v||0).toLocaleString('en-PK',{maximumFractionDigits:4}),date=v=>v?new Date(v).toLocaleDateString('en-GB',{timeZone:'Asia/Karachi'}):'—';
 const $=s=>root.querySelector(s),valid=t=>authorized()&&identity()===owner&&t===sequence;
 async function result(q){const r=await q;if(r.error)throw r.error;return r.data;}
 async function all(table,fields,key,id){let rows=[];for(let start=0;;start+=1000){const page=await result(db.from(table).select(fields).eq(key,id).order('created_at').order('id').range(start,start+999));rows.push(...(page||[]));if(!page||page.length<1000)return rows;}}
 const card=(label,value,unit='')=>`<div class="dashboard-balance"><div><span>${esc(label)}</span><strong>${esc(value)} <small>${esc(unit)}</small></strong></div></div>`;
 const notice=key=>errors[key]?`<p role="alert" class="note warn">${esc(key)} could not load. ${esc(errors[key])} <button type="button" class="btn small" data-refresh>Retry</button></p>`:'';
 function table(headers,rows){return `<div class="table-wrap"><table class="admin-preview-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell??'—')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">No records.</td></tr>`}</tbody></table></div>`;}
 function walletCards(){const w=data.wallets;return notice('wallets')+(w?`<div class="admin-member-metrics">${card('Cash',n(w.cash),'MIO')}${card('Proceed',n(w.proceed),'MIO')}${card('Shopping',n(w.shopping),'points')}${card('Promotion',n(w.promotion),'points')}${card('Exchange',errors.exchange?'Unavailable':n(data.exchange),'MIO')}</div>`:'')+notice('exchange');}
 function profileView(){return `<div class="admin-member-profile-grid">${[['Full name',record.full_name],['MIO ID',record.member_code],['Email',member.email],['Phone',record.phone],['Country',api.countryName(record.country_code)],['Gender',record.gender],['Date of birth',record.date_of_birth?date(record.date_of_birth+'T12:00:00Z'):null],['Sponsor',member.sponsor_name],['Sponsor MIO ID',member.sponsor_code],['Status',record.status],['Joined',date(record.created_at)]].map(([label,value])=>`<div><small>${esc(label)}</small><strong>${esc(value||'—')}</strong></div>`).join('')}</div><button type="button" class="btn primary" data-edit-profile>Edit profile</button>`;}
 function dashboard(){return notice('snapshot')+(data.snapshot?'<div data-dashboard-id="page-dashboard"></div><div hidden><div data-dashboard-id="dashboardProfile"></div><span data-dashboard-id="dashboardReceiveCode"></span><button data-dashboard-id="dashboardCopyCode"></button></div>':'<p>Dashboard values are unavailable. Retry to load this member’s current details.</p>');}
 function navigation(){const groups=[['Overview',[['dashboard','My Dashboard','layout'],['profile','My profile','user'],['network','My network','network']]],['Finance',[['earnings','Earnings','chart'],['wallets','My wallet','wallet'],['exchange','Exchange Wallet','transfer'],['transfer','Transfer MIO','transfer'],['transactions','Transaction history','history']]],['Marketplace',[['ecommerce','E-commerce','bag'],['orders','My orders','box'],['packages','Subscription Plans','diamond']]],['Account',[['security','Security','shield']]]];return groups.map(([title,links])=>`<section class="member-nav-group"><p>${title}</p>${links.map(([key,label,icon])=>`<button type="button" data-member-tab="${key}" class="${tab===key?'active':''}" aria-current="${tab===key?'page':'false'}">${window.MioDashboard.icon(icon)}<span>${label}</span></button>`).join('')}</section>`).join('');}
 function earningsSummary(){const totals=new Map();for(const row of data.opening||[])totals.set('Opening · MIO',(totals.get('Opening · MIO')||0)+Number(row.amount));for(const b of data.earnings||[]){const key=(b.currency||'MIO')+' · '+(b.status||'Unknown');totals.set(key,(totals.get(key)||0)+Number(b.payable_amount));}return notice('earnings')+`<div class="admin-member-metrics">${[...totals].map(([k,v])=>card(k,n(v))).join('')||'<p>No earnings recorded.</p>'}</div>`;}
 function render(){document.body.classList.remove('admin-support-menu-open');if(!record||!authorized()||identity()!==owner)return;presentation?.dispose();walletHistory?.dispose();api.releaseTree?.();const title=({exchange:'Exchange Wallet',transfer:'Transfer MIO',ecommerce:'E-commerce',security:'Security'}[tab]||tabs.find(t=>t[0]===tab)?.[1]||'Dashboard');root.innerHTML=`<header class="admin-member-banner"><div><small>ADMIN · MEMBER SUPPORT</small><strong>${esc(record.full_name)} <span>${esc(record.member_code)}</span></strong></div><button class="btn" type="button" data-refresh>Refresh</button><button class="btn" type="button" data-back>Back to Admin</button></header>${window.MioMemberManagement?.controls()||''}<div class="member-account-shell admin-support-shell"><button class="member-sidebar-backdrop" type="button" data-support-menu aria-label="Close account menu"></button><aside class="member-sidebar" aria-label="Member dashboard sections"><div class="sidebar-heading"><div><span>Member workspace</span><strong>Account centre</strong></div><button type="button" class="member-sidebar-close" data-support-menu aria-label="Close account menu">×</button></div><nav>${navigation()}</nav></aside><div class="member-workspace"><header class="member-topbar"><button type="button" data-support-menu aria-label="Toggle account menu" aria-expanded="false">${window.MioDashboard.icon('menu')}</button><strong tabindex="-1">${esc(title)}</strong><span class="member-header-date">${date(new Date())}</span><button type="button" data-support-theme aria-label="Switch dashboard theme">${window.MioDashboard.icon('moon')}</button><button type="button" data-member-tab="orders" aria-label="Member orders">${window.MioDashboard.icon('box')}</button></header><div class="member-page-content admin-support-content" data-member-content></div></div></div>`;let html='';if(tab==='dashboard')html=dashboard();if(tab==='profile')html=profileView();if(tab==='wallets')html='<section class="card cash-history-card"><div class="card-body" data-support-wallet-history></div></section>';if(tab==='exchange')html=notice('exchange')+card('Exchange Wallet',errors.exchange?'Unavailable':n(data.exchange),'MIO');if(tab==='transfer')html='<section class="dashboard-panel"><h2>Transfer support</h2><p>Review this member’s transfer history below. Transfers require the member’s own authorization.</p><button type="button" class="btn" data-member-tab="transactions">View transaction history</button></section>';if(tab==='ecommerce')html='<section class="dashboard-panel"><h2>E-commerce support</h2><p>Review this member’s orders and payment status. Use E-commerce Controls in Admin to update an order.</p><button type="button" class="btn" data-member-tab="orders">View member orders</button></section>';if(tab==='security')html='<section class="dashboard-panel"><h2>Account security</h2><p>Account status: '+esc(record.status)+'</p><p>Transaction PIN: '+(record.transaction_pin_set_at?'Configured':'Not configured')+'</p><p>Profile corrections can be saved from My profile after administrator verification. Passwords, PINs and authenticator secrets are never displayed.</p><button type="button" class="btn" data-member-tab="profile">Open profile</button></section>';if(tab==='earnings')html=earningsSummary()+notice('opening')+table(['Opening statement','Amount MIO'],(data.opening||[]).map(r=>[r.category,n(r.amount)]))+table(['Date','Bonus','Generation','Amount','Currency','Status'],(data.earnings||[]).slice().reverse().map(b=>[date(b.created_at),b.method,b.generation,n(b.payable_amount),b.currency,b.status]));if(tab==='packages')html=notice('packages')+table(['Package','Activated','Status','Base value'],(data.packages||[]).map(p=>[planName(p.package_code),date(p.activated_at),p.status,n(p.base_value)]));if(tab==='network')html=(api.mountTree?'':`<div class="admin-member-network-tabs">${[['generation','Generation'],['binary','Binary'],['single_line','Placement']].map(([key,label])=>`<button class="btn ${networkKind===key?'primary':''}" data-network-view="${key}" type="button">${label}</button>`).join('')}</div>`)+`<div data-member-network>Loading network…</div>`;if(tab==='orders')html=notice('orders')+table(['Order','Date','Status','Payment','Total PKR'],(data.orders||[]).slice().reverse().map(o=>[o.order_code,date(o.created_at),o.status,o.payment_status,n(o.total_pkr)]));if(tab==='transactions')html='<section class="card cash-history-card"><div class="card-body" data-support-wallet-history></div></section>';$('[data-member-content]').innerHTML=html;if(tab==='wallets'||tab==='transactions'){walletHistory=window.createMioWalletHistory({admin:true,host:()=>$('[data-support-wallet-history]')});walletHistory.mount({rpc:(name,args)=>db.rpc(name,args),error:e=>api.notify?.(e.message)});walletHistory.setIdentity(record.user_id);walletHistory.setWallet(selectedWallet);walletHistory.refresh();}if(tab==='dashboard'&&data.snapshot){presentation=window.createMioDashboardPresentation($('[data-member-content]'));presentation.renderSnapshot({...data.snapshot,summary:{...data.snapshot.summary,exchange_wallet_balance:errors.exchange?null:data.exchange}},{safeImage,planName,tierImage:api.tierImage});}if(tab==='network'){if(api.mountTree)api.mountTree($('[data-member-network]'),record.member_code,networkKind,(code,side)=>window.MioMemberManagement?.createForm(api,record,code,side,()=>open(member)));else loadNetwork();}}
 function transactionHistory(){const rows=(data.transactions||[]).slice().reverse();return `<div class="table-wrap"><table class="admin-preview-table"><thead><tr>${['Date','Action','Amount MIO','Reference','Reason'].map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td>${esc(date(r.created_at))}</td><td>${esc(r.action)}</td><td>${esc(n(r.amount))}</td><td>${window.MioTransferReceipt?.referenceMarkup(r.transfer_id||r.activation_id||r.id)||esc(r.transfer_id||r.activation_id||r.id)}</td><td>${esc(r.reason||'—')}</td></tr>`).join(''):'<tr><td colspan="5">No records.</td></tr>'}</tbody></table></div>`;}
 function incomeHistory(){const rows=data.snapshot?.incomeWallets?.ledger;if(!rows)return notice('snapshot');return table(['Date','Wallet','Amount','Activity','Note'],rows.map(r=>[date(r.created_at),r.wallet_kind,n(r.amount),r.entry_kind,r.note]));}
 async function loadNetwork(){const t=sequence,turn=++networkSequence,kind=networkKind;try{const value=await result(db.rpc('my_network_identity',{p_kind:kind,p_root_code:networkRootCode||record.member_code,p_depth:4}));if(!valid(t)||tab!=='network'||kind!==networkKind||turn!==networkSequence)return;const nodes=value?.nodes||[];$('[data-member-network]').innerHTML=`<p>Selected member’s ${esc(kind.replaceAll('_',' '))} tree · first 4 levels. Select a member to explore their branch.</p><div class="admin-member-tree">${nodes.map(node=>`<button type="button" class="admin-member-node" data-network-root="${esc(node.member_code)}"><small>Level ${Number(node.level??node.depth??0)} · ${esc(node.side||'')}</small><strong>${esc(node.full_name||'Member')}</strong><span>${esc(node.member_code)}</span><small>${esc(planName(node.package||node.package_code))} · ${esc(node.status||'')}</small></button>`).join('')||'<p>No members in this network.</p>'}</div><button type="button" class="btn" data-network-reset>Return to selected member</button>`;}catch(e){if(valid(t)&&tab==='network')$('[data-member-network]').textContent='Could not load network: '+e.message;}}
 async function open(row){if(!authorized())throw Error('Admin access required');owner=identity();member={...row};record=null;data={};errors={};tab='dashboard';networkRootCode=null;api.releaseTree?.();presentation?.dispose();root.hidden=false;document.body.classList.add('admin-member-support-active');const t=++sequence;root.innerHTML='<p role="status">Loading member dashboard…</p>';try{const p=await result(db.from('member_profiles').select('user_id,member_code,full_name,phone,country_code,gender,date_of_birth,sponsor_id,status,created_at,achieved_rank,profile_photo_url,transaction_pin_set_at').eq('user_id',row.user_id).maybeSingle());if(!valid(t))return;if(!p)throw Error('Member not found or access unavailable');record=p;const tasks={opening:()=>result(db.from('member_opening_earnings').select('category,amount,updated_at').eq('member_id',p.user_id)),snapshot:()=>result(db.rpc('admin_member_dashboard',{p_member_id:p.user_id})).then(value=>{if(value?.member_id!==p.user_id||!value.summary||!value.financial)throw Error('Member dashboard identity could not be verified');return value;}),wallets:()=>result(db.rpc('admin_network_control_members',{p_offset:0,p_limit:100,p_package:null,p_search:p.member_code})).then(r=>{const w=r?.rows?.find(x=>x.member_id===p.user_id);if(!w)throw Error('Member wallet record unavailable');return w;}),exchange:()=>result(db.rpc('admin_network_control_exchange',{p_offset:0,p_limit:100,p_search:p.member_code})).then(r=>{const w=r?.rows?.find(x=>x.member_id===p.user_id);if(!w)throw Error('Member exchange record unavailable');return w.exchange;}),points:()=>all('point_ledger','id,point_type,amount,created_at','member_id',p.user_id),earnings:()=>all('bonus_transactions','id,method,payable_amount,currency,status,generation,created_at','beneficiary_id',p.user_id),packages:()=>result(db.from('package_activations').select('package_code,activated_at,status,base_value').eq('member_id',p.user_id).order('activated_at',{ascending:false})),maintenance:()=>result(db.from('member_maintenance').select('monthly_due_at,annual_due_at,monthly_progress_ppv').eq('member_id',p.user_id).maybeSingle()),orders:()=>all('orders','id,order_code,created_at,status,payment_status,total_pkr','buyer_id',p.user_id)};await Promise.all(Object.entries(tasks).map(async([key,fn])=>{try{const value=await fn();if(valid(t))data[key]=value;}catch(e){if(valid(t))errors[key]=e.message;}}));if(valid(t))render();}catch(e){if(valid(t)){root.innerHTML=`<p role="alert">${esc(e.message)}</p><button class="btn" type="button" data-refresh>Retry</button><button class="btn" type="button" data-back>Back to Account Holders</button>`;}}}
 function edit(){const p=record;$('[data-member-content]').innerHTML=`<form class="form admin-member-edit"><label>Full name<input name="full_name" required minlength="2" maxlength="150" value="${esc(p.full_name)}"></label><label>Phone<input name="phone" required minlength="5" maxlength="40" value="${esc(p.phone||'')}"></label><label>Country<select name="country" required>${countryOptions(p.country_code)}</select></label><label>Gender<select name="gender"><option value="">Not set</option><option value="male">Male</option><option value="female">Female</option></select></label><label>Date of birth<input type="date" name="dob" min="1900-01-01" max="${new Date().toISOString().slice(0,10)}" value="${esc(p.date_of_birth||'')}"></label><label>Reason for change<textarea name="reason" minlength="10" maxlength="2000" required></textarea></label><p data-save-status role="status"></p><div><button type="submit" class="btn primary">Verify & Save</button> <button type="button" class="btn" data-cancel-edit>Cancel</button></div></form>`;$('[name="gender"]').value=p.gender||'';$('[name="full_name"]').focus();}
 root.addEventListener('click',e=>{const copy=e.target.closest('[data-copy-reference]');if(copy){e.stopPropagation();window.MioTransferReceipt?.copyReference(copy);return;}if(e.target.closest('#treeCard'))return;e.stopPropagation();const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-back')){clear();onClose();return;}if(!authorized()||identity()!==owner)return;if(b.dataset.manageSection){window.MioMemberManagement?.edit(api,record,b.dataset.manageSection,()=>open(member));return;}if(b.hasAttribute('data-refresh')){if(member)open(member);return;}if(b.hasAttribute('data-support-menu')){const shell=$('.admin-support-shell');shell.classList.toggle(window.innerWidth>800?'sidebar-collapsed':'sidebar-open');document.body.classList.toggle('admin-support-menu-open',window.innerWidth<=800&&shell.classList.contains('sidebar-open'));b.setAttribute('aria-expanded',String(shell.classList.contains('sidebar-open')));return;}if(b.hasAttribute('data-support-theme')){const shell=$('.admin-support-shell');shell.dataset.theme=shell.dataset.theme==='dark'?'light':'dark';return;}if(b.dataset.walletHistory){selectedWallet=b.dataset.walletHistory;tab='wallets';render();return;}if(b.hasAttribute('data-shopping-wallet')){tab='wallets';render();return;}if(b.dataset.copy){navigator.clipboard?.writeText(b.dataset.copy);return;}if(b.dataset.dashboardGeneration){presentation?.showDetail('generation',Number(b.dataset.dashboardGeneration));return;}if(b.dataset.dashboardDetail){presentation?.showDetail(b.dataset.dashboardDetail);return;}if(b.dataset.dashboardTree){networkKind=b.dataset.dashboardTree;tab='network';render();return;}if(b.dataset.page){const routes={dashboard:'dashboard',profile:'profile',wallet:'wallets',earnings:'earnings',packages:'packages',network:'network','network-graphical':'network',orders:'orders',transactions:'transactions'};if(routes[b.dataset.page]){tab=routes[b.dataset.page];render();}return;}if(b.dataset.memberTab){tab=b.dataset.memberTab;render();}if(b.hasAttribute('data-edit-profile'))edit();if(b.hasAttribute('data-cancel-edit'))render();if(b.dataset.networkView){networkKind=b.dataset.networkView;networkRootCode=null;render();}if(b.dataset.networkRoot){networkRootCode=b.dataset.networkRoot;loadNetwork();}if(b.hasAttribute('data-network-reset')){networkRootCode=null;loadNetwork();}});
 root.addEventListener('keydown',e=>{if(e.key==='Escape')$('.admin-support-shell')?.classList.remove('sidebar-open');});
 root.addEventListener('submit',async e=>{e.stopPropagation();if(!e.target.matches('.admin-member-edit'))return;e.preventDefault();const form=e.target;if(busy||!authorized()||identity()!==owner||!form.reportValidity())return;busy=true;const t=sequence,id=record.user_id,button=form.querySelector('[type="submit"]'),status=form.querySelector('[data-save-status]');button.disabled=true;try{const payload={p_member_id:id,p_name:form.elements.full_name.value.trim(),p_phone:form.elements.phone.value.trim(),p_country:form.elements.country.value,p_gender:form.elements.gender.value||null,p_date_of_birth:form.elements.dob.value||null,p_reason:form.elements.reason.value.trim()};await confirmSensitive('Save profile changes for '+record.member_code);if(!valid(t))return;await result(db.rpc('admin_save_member_profile',payload));if(!valid(t))return;await open({...member,full_name:payload.p_name,phone:payload.p_phone,country_code:payload.p_country});tab='profile';render();$('[data-member-content]').insertAdjacentHTML('afterbegin','<p role="status" class="note">Profile saved successfully.</p>');onSaved();}catch(e){if(valid(t))status.textContent='Could not save: '+e.message;}finally{busy=false;button.disabled=false;}});
 function clear(){api.releaseTree?.();presentation?.dispose();walletHistory?.dispose();document.body.classList.remove('admin-member-support-active','admin-support-menu-open');sequence++;member=null;record=null;data={};errors={};owner=null;root.replaceChildren();root.hidden=true;}
 return {open,clear};
}};
